def count_digit_runs(s):
    count = 0
    in_run = False
    for c in s:
        if c.isdigit():
            if not in_run:
                count += 1
                in_run = True
        else:
            in_run = False
    return count

def is_two_strings_isomorphic(a, b):
    if len(a) != len(b):
        return False
    map_ab = {}
    map_ba = {}
    for ca, cb in zip(a, b):
        if ca in map_ab:
            if map_ab[ca] != cb:
                return False
        else:
            map_ab[ca] = cb
        if cb in map_ba:
            if map_ba[cb] != ca:
                return False
        else:
            map_ba[cb] = ca
    return True

def first_and_last_char_same(s):
