def count_letter_digit_symbol_groups(s):
    if len(s) == 0:
        return 0
    def cls(c):
        if c.isalpha():
            return 'L'
        elif c.isdigit():
            return 'D'
        else:
            return 'S'
    count = 1
    prev = cls(s[0])
    for c in s[1:]:
        cur = cls(c)
        if cur != prev:
            count += 1
            prev = cur
    return count

