def longest_common_prefix_case_insensitive(strs):
    if not strs:
        return ''
    first = strs[0]
    min_len = min(len(s) for s in strs)
    prefix_len = 0
    for i in range(min_len):
        c = first[i].lower()
        if all(s[i].lower() == c for s in strs):
            prefix_len += 1
        else:
            break
    return first[:prefix_len]

