def is_anagram(a, b):
    def normalize(x):
        return sorted(c.lower() for c in x if c != ' ')
    return normalize(a) == normalize(b)

def swap_case(s):
    result = []
    for c in s:
        if c.isupper():
            result.append(c.lower())
        elif c.islower():
            result.append(c.upper())
        else:
            result.append(c)
    return ''.join(result)

def is_balanced_parens(s):
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
            if balance < 0:
                return False
        else:
            return False
    return balance == 0

