def is_balanced_ignoring_escapes(s):
    balance = 0
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '\\' and i + 1 < n and s[i + 1] in '()':
            i += 2
            continue
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
            if balance < 0:
                return False
        i += 1
    return balance == 0

